class stack:

	def __init__(self):
		self.s = []
		self.minEle = -1
		self.length = 0

	def push(self, x):
		if len(self.s) == 0:
			self.s.append(x)
			self.minEle = x
			self.length += 1
		elif x > self.minEle:
			self.s.append(x)
			self.length += 1
		else:
			topel = 2 * x - self.minEle
			self.s.append(topel)
			self.length += 1
			self.minEle = x

	def pop(self):
		if len(self.s) != 0:
			if self.s[-1] < self.minEle:
				a = self.minEle
				self.minEle = 2 * self.minEle - self.s[-1]
				if len(self.s) == 1:
					self.minEle = -1
				self.length -= 1
				self.s.pop()
				return a
			else:
				if len(self.s) == 1:
					self.minEle = -1
				self.length -= 1
				return self.s.pop()
		else:
			return -1

	def getMin(self):
		return self.minEle
